const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let idx = 0;
const len = data.length;

function nextInt() {
  while (idx < len && data.charCodeAt(idx) <= 32) idx++;
  let num = 0;
  while (idx < len) {
    const c = data.charCodeAt(idx);
    if (c <= 32) break;
    num = num * 10 + (c - 48);
    idx++;
  }
  return num;
}

const E = nextInt();
const M = nextInt();
const D = nextInt();

const likeX = new Int32Array(M);
const likeY = new Int32Array(M);
for (let i = 0; i < M; i++) {
  likeX[i] = nextInt();
  likeY[i] = nextInt();
}

const dislikeX = new Int32Array(D);
const dislikeY = new Int32Array(D);
for (let i = 0; i < D; i++) {
  dislikeX[i] = nextInt();
  dislikeY[i] = nextInt();
}

const group = new Int32Array(E + 1);
const G = E / 3;
for (let g = 0; g < G; g++) {
  const a = nextInt();
  const b = nextInt();
  const c = nextInt();
  group[a] = g;
  group[b] = g;
  group[c] = g;
}

let ans = 0;
for (let i = 0; i < M; i++) {
  if (group[likeX[i]] !== group[likeY[i]]) ans++;
}
for (let i = 0; i < D; i++) {
  if (group[dislikeX[i]] === group[dislikeY[i]]) ans++;
}

process.stdout.write(String(ans));
